1	import './style.css'
2	import * as BABYLON from '@babylonjs/core';
3	
4	interface Ability {
5	  name: string;
6	  icon: string;
7	  keybind: string;
8	  type: 'basic' | 'threshold' | 'ultimate';
9	}
10	
11	const MELEE_ABILITIES: Ability[] = [
12	  { name: "Attack", icon: "attack-.png", keybind: "1", type: "basic" },
13	  { name: "Slice", icon: "slice.png", keybind: "2", type: "basic" },
14	  { name: "Sever", icon: "sever.png", keybind: "3", type: "basic" },
15	  { name: "Fury", icon: "fury.png", keybind: "4", type: "basic" },
16	  { name: "Decimate", icon: "decimate.png", keybind: "5", type: "basic" },
17	  { name: "Cleave", icon: "cleave.png", keybind: "6", type: "basic" },
18	  { name: "Smash", icon: "smash.png", keybind: "7", type: "basic" },
19	  { name: "Hurricane", icon: "hurricane.png", keybind: "Q", type: "threshold" },
20	  { name: "Assault", icon: "assault.png", keybind: "W", type: "threshold" },
21	  { name: "Quake", icon: "quake.png", keybind: "E", type: "threshold" },
22	  { name: "Berserk", icon: "berserk.png", keybind: "R", type: "ultimate" },
23	  { name: "Meteor Strike", icon: "meteor-strike.png", keybind: "T", type: "ultimate" },
24	  { name: "Overpower", icon: "overpower.png", keybind: "Y", type: "ultimate" },
25	  { name: "Freedom", icon: "freedom.png", keybind: "F", type: "basic" },
26	];
27	
28	class SovereignUnifiedHUD {
29	  private engine: BABYLON.Engine;
30	  private scene: BABYLON.Scene;
31	  private adrenaline = 0;
32	  private logElement: HTMLElement;
33	  private barElement: HTMLElement;
34	  private fillElement: HTMLElement;
35	
36	  constructor() {
37	    this.logElement = document.getElementById('log')!;
38	    this.barElement = document.getElementById('action-bar')!;
39	    this.fillElement = document.getElementById('adrenaline-fill')!;
40	    
41	    const canvas = document.getElementById('renderCanvas') as HTMLCanvasElement;
42	    this.engine = new BABYLON.Engine(canvas, true);
43	    this.scene = new BABYLON.Scene(this.engine);
44	    
45	    this.init3D();
46	    this.init2D();
47	    this.connectBridge();
48	    
49	    this.engine.runRenderLoop(() => {
50	      this.scene.render();
51	    });
52	    
53	    window.addEventListener('resize', () => this.engine.resize());
54	  }
55	
56	  private init3D() {
57	    this.scene.clearColor = new BABYLON.Color4(0.02, 0.03, 0.04, 1);
58	    
59	    const camera = new BABYLON.ArcRotateCamera("camera", -Math.PI / 2, Math.PI / 2.5, 3, new BABYLON.Vector3(0, 0, 0), this.scene);
60	    camera.attachControl(document.getElementById('renderCanvas'), true);
61	    camera.lowerRadiusLimit = 2;
62	    camera.upperRadiusLimit = 10;
63	
64	    const light = new BABYLON.HemisphericLight("light", new BABYLON.Vector3(0, 1, 0), this.scene);
65	    light.intensity = 0.7;
66	
67	    // Create a mock avatar point cloud
68	    this.createMockAvatar();
69	  }
70	
71	  private createMockAvatar() {
72	    const pcs = new BABYLON.PointsCloudSystem("pcs", 2, this.scene);
73	    const count = 2000;
74	    
75	    pcs.addPoints(count, (particle, i) => {
76	        const phi = Math.acos(-1 + (2 * i) / count);
77	        const theta = Math.sqrt(count * Math.PI) * phi;
78	        
79	        // Sphere-like distribution for now
80	        particle.position = new BABYLON.Vector3(
81	            Math.sin(phi) * Math.cos(theta) * 0.5,
82	            Math.cos(phi) * 1.0, // Humanoid-ish height
83	            Math.sin(phi) * Math.sin(theta) * 0.5
84	        );
85	        particle.color = new BABYLON.Color4(0, 0.8, 1, 0.5);
86	    });
87	    
88	    pcs.buildMeshAsync();
89	  }
90	
91	  private init2D() {
92	    this.renderBar();
93	    this.addLog('Unified Substrate active. Connecting...');
94	  }
95	
96	  private renderBar() {
97	    this.barElement.innerHTML = '';
98	    MELEE_ABILITIES.forEach((ability) => {
99	      const slot = document.createElement('div');
100	      slot.className = `ability-slot ${ability.type}`;
101	      slot.innerHTML = `
102	        <span class="slot-key">${ability.keybind}</span>
103	        <img src="/icons/${ability.icon}" alt="${ability.name}" onerror="this.src='https://via.placeholder.com/40/00d2ff/ffffff?text=${ability.name[0]}'">
104	      `;
105	      this.barElement.appendChild(slot);
106	    });
107	  }
108	
109	  private connectBridge() {
110	    const ws = new WebSocket('ws://localhost:8080');
111	    ws.onopen = () => {
112	      this.addLog('Linked to Sovereign Engine.');
113	      const indicator = document.getElementById('engine-status');
114	      if (indicator) {
115	        indicator.style.background = '#34d399';
116	        indicator.style.boxShadow = '0 0 10px #34d399';
117	      }
118	    };
119	    ws.onmessage = (event) => {
120	      const data = JSON.parse(event.data);
121	      if (data.type === 'STATE_UPDATE') {
122	        this.setAdrenaline(data.adrenaline);
123	        const arch = document.getElementById('archetype-name');
124	        if (arch) arch.innerText = data.activeArchetype.toUpperCase();
125	        if (data.lastAction) {
126	          this.highlightAbility(data.lastAction);
127	        }
128	        if (data.learningTrace) {
129	          this.renderCausalChain(data.learningTrace);
130	        }
131	      } else if (data.type === 'LOG_UPDATE') {
132	        this.addLog(data.message, data.level);
133	      } else if (data.type === 'HITSPLAT') {
134	        this.showHitsplat(data.value, data.kind);
135	      }
136	    };
137	    ws.onclose = () => {
138	      this.addLog('Link severed. Retrying...', 'info');
139	      const indicator = document.getElementById('engine-status');
140	      if (indicator) {
141	        indicator.style.background = '#ef4444';
142	        indicator.style.boxShadow = '0 0 10px #ef4444';
143	      }
144	      setTimeout(() => this.connectBridge(), 2000);
145	    };
146	  }
147	
148	  private showHitsplat(value: number, kind: string) {
149	    // Basic screen-space hitsplat logic (or 3D world space)
150	    const container = document.createElement('div');
151	    container.style.position = 'absolute';
152	    container.style.left = '50%';
153	    container.style.top = '50%';
154	    container.style.transform = 'translate(-50%, -50%)';
155	    container.style.pointerEvents = 'none';
156	    container.style.zIndex = '100';
157	    
158	    const color = kind === 'CRIT' ? '#ffcc00' : (kind === 'POISON' ? '#00cc00' : '#ff4444');
159	    const size = kind === 'CRIT' ? '48px' : '32px';
160	    
161	    container.innerHTML = `<span style="color: ${color}; font-size: ${size}; font-weight: 800; filter: drop-shadow(0 0 10px ${color}); transition: all 0.5s ease-out;">${value}</span>`;
162	    document.body.appendChild(container);
163	    
164	    // Animate up and fade
165	    setTimeout(() => {
166	        container.style.transform = 'translate(-50%, -150%) scale(1.5)';
167	        container.style.opacity = '0';
168	    }, 10);
169	    
170	    setTimeout(() => container.remove(), 1000);
171	  }
172	
173	  private setAdrenaline(value: number) {
174	    this.adrenaline = Math.max(0, Math.min(100, value));
175	    this.fillElement.style.width = `${this.adrenaline}%`;
176	    if (this.adrenaline >= 100) {
177	      this.fillElement.style.boxShadow = '0 0 30px var(--neon-blue)';
178	      this.fillElement.style.background = 'linear-gradient(90deg, var(--neon-blue), var(--neon-purple))';
179	    } else {
180	      this.fillElement.style.boxShadow = '0 0 20px rgba(255, 157, 0, 0.5)';
181	      this.fillElement.style.background = 'linear-gradient(90deg, var(--adrenaline-orange), #ff4d00)';
182	    }
183	  }
184	
185	  private highlightAbility(name: string) {
186	    const slots = document.querySelectorAll('.ability-slot');
187	    slots.forEach(slot => {
188	      const img = slot.querySelector('img');
189	      if (img && (img.alt === name || img.alt.toLowerCase() === name.toLowerCase())) {
190	        slot.classList.add('active-fire');
191	        setTimeout(() => slot.classList.remove('active-fire'), 600);
192	      }
193	    });
194	  }
195	
196	  private addLog(message: string, type: 'info' | 'action' = 'info') {
197	    const entry = document.createElement('div');
198	    entry.className = `log-entry ${type === 'action' ? 'action' : ''}`;
199	    const time = new Date().toLocaleTimeString([], { hour12: false, hour: '2-digit', minute: '2-digit', second: '2-digit' });
200	    entry.innerText = `[${time}] ${message}`;
201	    this.logElement.prepend(entry);
202	    if (this.logElement.childNodes.length > 20) this.logElement.lastChild?.remove();
203	  }
204	
205	  private renderCausalChain(evidence: any[]) {
206	    const panel = document.getElementById('causality-panel');
207	    if (!panel) return;
208	
209	    panel.innerHTML = '';
210	    
211	    // Group and filter relevant signals for the timeline
212	    // We want a flow: Resolution -> Gate Checks -> Decision
213	    const flowGroups = [
214	      { label: 'Sync', signals: ['GATE_CHANNEL_LOCKED', 'GATE_GCD_LOCKED'] },
215	      { label: 'Target', signals: ['GATE_TARGET_DEAD', 'GATE_PVME_TARGET_SWITCH'] },
216	      { label: 'Rotation', signals: ['PVME_SEQUENCE_LOCKED', 'ARCHETYPE_FALLBACK'] },
217	      { label: 'Constraints', signals: ['GATE_RANGE_PASSED', 'GATE_RANGE_FAILED', 'GATE_COOLDOWN_PASSED', 'GATE_COOLDOWN_FAILED', 'GATE_ADRENALINE_PASSED', 'GATE_ADRENALINE_FAILED'] },
218	      { label: 'Decision', signals: ['INTENT_COMMITTED', 'BUILD_PHASE_TRIGGERED', 'ABILITY_CATEGORY_MISMATCH'] }
219	    ];
220	
221	    flowGroups.forEach(group => {
222	      const groupEvidence = evidence.filter(e => group.signals.includes(e.signal));
223	      if (groupEvidence.length === 0 && group.label !== 'Decision') return;
224	
225	      const node = document.createElement('div');
226	      node.className = 'causal-node';
227	      
228	      const isFailed = groupEvidence.some(e => e.signal.includes('FAILED') || e.signal.includes('LOCKED') || e.signal.includes('DEAD') || e.signal.includes('MISMATCH'));
229	      const isFallback = groupEvidence.some(e => e.signal.includes('FALLBACK') || e.signal.includes('BUILD_PHASE'));
230	      
231	      let statusClass = '';
232	      if (isFailed) statusClass = 'failed';
233	      else if (isFallback) statusClass = 'fallback';
234	
235	      const lastSignal = groupEvidence[groupEvidence.length - 1];
236	      const detailStr = lastSignal ? JSON.stringify(lastSignal.detail).replace(/[{}\"]/g, '') : 'WAITING';
237	      const maxElapsed = groupEvidence.length > 0 ? Math.max(...groupEvidence.map(e => e.elapsedMs || 0)) : 0;
238	      const timingStr = maxElapsed > 0 ? `${maxElapsed.toFixed(2)}ms` : '';
239	
240	      node.innerHTML = `
241	        <div class="node-dot ${statusClass}"></div>
242	        <div class="node-label">${group.label}</div>
243	        <div class="node-timing">${timingStr}</div>
244	        <div class="node-detail" title="${detailStr}">${detailStr}</div>
245	        <div class="node-connector"></div>
246	      `;
247	      panel.appendChild(node);
248	    });
249	  }
250	}
251	
252	new SovereignUnifiedHUD();
