1	import { createRequire } from 'module';
2	const require = createRequire(import.meta.url);
3	import { VisionActuationHarness } from '../engines/VisionActuationHarness.js';
4	import { ChromanumberEngine } from '../engines/ChromanumberEngine.js';
5	import { SpatialVisionEngine } from '../engines/SpatialVisionEngine.js';
6	import { Renderer } from '../ui/Renderer.js';
7	import { ModelClient } from '../clients/ModelClient.js';
8	import { SovereignConfig } from '../config/SovereignConfig.js';
9	import { createLogger } from '../utils/logger.js';
10	import path from 'path';
11	import { readFileSync, writeFileSync, copyFileSync, existsSync } from 'fs';
12	
13	import { HexagramManager } from '../routing/HexagramManager.js';
14	
15	const logger = createLogger('LiveVisionLoop');
16	
17	async function runLiveCycle() {
18	    logger.info('Commencing Phase 15 Live Operational Cycle');
19	
20	    // Initialize CNS singletons
21	    const hexagram = new HexagramManager(null, 'test-project');
22	    (globalThis as any).hexagram = hexagram;
23	
24	    const config: SovereignConfig = {
25	        visionModel: 'ollama:llava',
26	        codingHeavyModel: 'kimi-k2.6:cloud',
27	        codingFastModel: 'ollama:qwen2.5-coder:1.5b',
28	        ollamaBaseUrl: 'http://localhost:11434',
29	    } as any;
30	
31	    const client = new ModelClient(config);
32	    const renderer = new Renderer();
33	    const spatialVision = SpatialVisionEngine.getInstance(config, renderer);
34	    const engine = ChromanumberEngine.getInstance();
35	    const harness = new VisionActuationHarness(engine, spatialVision);
36	
37	    const { getrsmvSubstratePath } = await import('../utils/SovereignPathResolver.js');
38	    const targetFile = path.resolve(getrsmvSubstratePath(), 'src', '3d', 'test_substrate.ts');
39	    const backupFile = targetFile + '.bak';
40	
41	    try {
42	        if (!existsSync(targetFile)) {
43	            logger.warn({ targetFile }, 'Target substrate not found. Skipping physical mutation.');
44	            return;
45	        }
46	
47	        // 1. Create backup
48	        logger.info({ targetFile }, 'Creating substrate backup');
49	        copyFileSync(targetFile, backupFile);
50	
51	        // 2. Run Cycle
52	        const testUrl = 'https://example.com';
53	        const prompt = 'Mutate the shader in test_substrate to use a crimson (#DC143C) aesthetic for the primary color.';
54	
55	        logger.info('Triggering perception-action loop...');
56	        const result = await harness.runCycle(testUrl, prompt);
57	
58	        if (result.ok && result.value.success) {
59	            logger.info({ details: result.value.details }, 'CYCLE SUCCESSFUL');
60	
61	            // 3. Verify Mutation
62	            const content = readFileSync(targetFile, 'utf-8');
63	            if (content.includes('#DC143C')) {
64	                logger.info('VERIFICATION PASSED: AST Mutation reflected in substrate.');
65	            } else {
66	                logger.error('VERIFICATION FAILED: Mutation not found in file content.');
67	            }
68	        } else {
69	            logger.error({
70	                error: result.ok ? 'Actuation reported failure' : result.error?.message,
71	                details: result.ok ? result.value.details : undefined
72	            }, 'CYCLE FAILED');
73	        }
74	
75	    } catch (err) {
76	        logger.error({ err }, 'Operational cycle crashed');
77	    } finally {
78	        // 4. Restore and Cleanup
79	        if (existsSync(backupFile)) {
80	            logger.info('Restoring substrate integrity');
81	            copyFileSync(backupFile, targetFile);
82	        }
83	        await harness.shutdown();
84	        logger.info('Live Vision Loop terminated.');
85	    }
86	}
87	
88	runLiveCycle().catch(console.error);
