1	import { createRequire } from 'module';
2	const require = createRequire(import.meta.url);
3	import { spawn } from 'child_process';
4	import { promises as fs } from 'fs';
5	import { join } from 'path';
6	import { createLogger } from '../utils/logger.js';
7	import { WikiEnricher } from '../utils/WikiEnricher.js';
8	import { getrsmvCachePath, getrsmvSubstratePath } from '../utils/SovereignPathResolver.js';
9	import type { Result, PedagogyProfile } from '../core/models.js';
10	
11	const logger = createLogger('TransientObserver');
12	
13	/**
14	 * TransientObserver â€” Coordinates the "Observe -> Distill -> Purge" pedagogy loop.
15	 */
16	export class TransientObserver {
17	    private static instance: TransientObserver | undefined;
18	    private eye: any = null;
19	    private lastCaptureTime = 0;
20	    private lastCaptureResult: any = null;
21	    private static readonly CAPTURE_THROTTLE_MS = 5000; // Live vision loop cadence
22	
23	    public static getInstance(): TransientObserver {
24	        if (!this.instance) {
25	            this.instance = new TransientObserver();
26	        }
27	        return this.instance;
28	    }
29	
30	    private constructor() { }
31	
32	    /**
33	     * Study a professional asset to learn its production norms.
34	     */
35	    public async study(modelId: string): Promise<Result<PedagogyProfile>> {
36	        logger.info({ modelId }, 'Starting production pedagogy study');
37	
38	        try {
39	            // 1. Semantic Enrichment (Wiki)
40	            // Extract a name hint from the ID if possible (e.g., npc:0 -> Hans mapping)
41	            // In a real scenario, this would use a Cache-to-Lore mapping table.
42	            const nameHint = modelId === 'npc:0' ? 'Hans' : (modelId.startsWith('npc:') ? 'NPC' : 'unknown');
43	            const wikiResult = await WikiEnricher.enrich(nameHint);
44	
45	            // 2. Headless Rendering & Analysis
46	            const cachePath = getrsmvCachePath();
47	            const pedagogyProfilePath = join(process.cwd(), 'pedagogy_profile.json');
48	            const wikiContextPath = join(process.cwd(), 'wiki_context.json');
49	
50	            // Write wiki context to file to avoid shell escaping issues
51	            if (wikiResult.ok) {
52	                await fs.writeFile(wikiContextPath, JSON.stringify(wikiResult.value));
53	            }
54	
55	            // Spawn headless CLI with --analyze and --wiki (as file path)
56	            const npxCmd = process.platform === 'win32' ? 'npx.cmd' : 'npx';
57	            const subprocess = spawn(npxCmd, [
58	                'tsx', join(getrsmvSubstratePath(), 'src', 'headless', 'cli.ts'),
59	                '--model', modelId,
60	                '--source', `cache:${cachePath}`,
61	                '--analyze',
62	                ...(wikiResult.ok ? ['--wiki', 'wiki_context.json'] : [])
63	            ], {
64	                shell: true,
65	                env: { ...process.env, POG_rsmv_CACHE_DIR: cachePath }
66	            });
67	
68	            let output = '';
69	            subprocess.stdout?.on('data', d => output += d);
70	            subprocess.stderr?.on('data', d => output += d);
71	
72	            await new Promise((resolve, reject) => {
73	                subprocess.on('exit', (code) => {
74	                    if (code === 0) resolve(true);
75	                    else {
76	                        logger.error({ code, output }, 'Headless analysis subprocess failed');
77	                        reject(new Error(`Headless analysis failed with code ${code}`));
78	                    }
79	                });
80	            });
81	
82	            // 3. Ingest Distilled Wisdom
83	            const profileData = await fs.readFile(pedagogyProfilePath, 'utf8');
84	            const profile = JSON.parse(profileData) as PedagogyProfile;
85	
86	            // 4. Final Semantic Fusion (Fusion Layer)
87	            if (wikiResult.ok) {
88	                const lore = wikiResult.value;
89	                (profile.semantics as any).loreExtract = lore.intent;
90	                (profile.semantics as any).wikiVariables = lore.variables;
91	                if (lore.race) (profile.semantics as any).race = lore.race;
92	
93	                // Extract combat level from variables if present
94	                if (lore.variables?.combat) {
95	                    (profile.metrics as any).combatLevel = parseInt(lore.variables.combat);
96	                }
97	            }
98	
99	            // 5. Cleanup (The Purge)
100	            await this.cleanup();
101	
102	            logger.info({ modelId, polyCount: profile.metrics.polyCount, combatLevel: (profile.metrics as any).combatLevel }, 'Pedagogy study complete');
103	            return { ok: true, value: profile };
104	
105	        } catch (err) {
106	            logger.error({ err, modelId }, 'Pedagogy study failed');
107	            return { ok: false, error: err as Error };
108	        }
109	    }
110	
111	    /**
112	     * Observe: A real-time perceptual probe that combines pixel sampling with semantic context.
113	     * This is the "Live" version of Study.
114	     */
115	    public async observe(targetName: string, imagePath: string): Promise<Result<any>> {
116	        logger.info({ targetName }, 'Initiating real-time chromatic observation');
117	
118	        // 1. Live Vision Loop — reuse singleton eye, throttle captures
119	        let activePath = imagePath;
120	        const now = Date.now();
121	        if (imagePath === 'latest_frame.png') {
122	            // Throttle: skip capture if within cadence window and we have a cached result
123	            if (this.lastCaptureResult && (now - this.lastCaptureTime) < TransientObserver.CAPTURE_THROTTLE_MS) {
124	                activePath = this.lastCaptureResult;
125	            } else {
126	                // Reuse singleton eye (never allocate a new one per tick)
127	                if (!this.eye) {
128	                    this.eye = new (require('../utils/SovereignEye.js')).SovereignEye('live-vision-loop');
129	                }
130	                const port = (require('../monitor/SwitchboardLimb.js')).SwitchboardLimb.getInstance().getActivePort() || 8788;
131	                const captureRes = await this.eye.capture({ type: 'url', target: `http://localhost:${port}/edge_radar.html` });
132	                if (captureRes.ok && captureRes.value.imagePath) {
133	                    activePath = captureRes.value.imagePath;
134	                    this.lastCaptureResult = activePath;
135	                    this.lastCaptureTime = now;
136	                    // Copy to bridge
137	                    const { copyFileSync } = require('fs');
138	                    copyFileSync(activePath, 'latest_frame.png');
139	                }
140	            }
141	        }
142	
143	        // 2. Get Wiki Ground Truth
144	        const wikiRes = await WikiEnricher.enrich(targetName);
145	        const expectedPalette: string[] = [];
146	
147	        if (wikiRes.ok && wikiRes.value.variables) {
148	            const vars = wikiRes.value.variables;
149	            if (vars.hex1) expectedPalette.push(vars.hex1);
150	            if (vars.hex2) expectedPalette.push(vars.hex2);
151	            if (vars.color) expectedPalette.push(vars.color);
152	        }
153	
154	        return {
155	            ok: true,
156	            value: {
157	                name: targetName,
158	                imagePath: activePath,
159	                wikiLore: wikiRes.ok ? wikiRes.value.intent : 'Unknown',
160	                expectedPalette,
161	                timestamp: Date.now()
162	            }
163	        };
164	    }
165	
166	    /**
167	     * Delete temporary render and analysis artifacts.
168	     */
169	    private async cleanup() {
170	        const files = ['model.png', 'model.glb', 'pedagogy_profile.json', 'wiki_context.json'];
171	        for (const file of files) {
172	            try {
173	                await fs.unlink(join(process.cwd(), file));
174	            } catch (e) {
175	                // Ignore missing files
176	            }
177	        }
178	    }
179	}
