1	import { WikiEnricher, WikiRotation } from './WikiEnricher.js';
2	import { createLogger } from './logger.js';
3	import { writeFileSync, existsSync, mkdirSync } from 'fs';
4	import { join } from 'path';
5	
6	const logger = createLogger('PVMEIngester');
7	
8	export class PVMEIngester {
9	    private static DATA_DIR = join(process.cwd(), 'data', 'pvme');
10	
11	    /**
12	     * Pull rotations for a list of bosses and save to JSON.
13	     */
14	    public static async ingestBosses(bossNames: string[]): Promise<void> {
15	        if (!existsSync(this.DATA_DIR)) {
16	            mkdirSync(this.DATA_DIR, { recursive: true });
17	        }
18	
19	        for (const boss of bossNames) {
20	            try {
21	                logger.info({ boss }, 'Ingesting PVME data for boss');
22	                const rotations = await WikiEnricher.fetchRotations(boss);
23	                const bestiary = await WikiEnricher.fetchBestiaryData(boss);
24	
25	                // Sanitize and download icons
26	                const iconDir = join(process.cwd(), 'web_hud', 'public', 'icons');
27	                for (const rot of rotations) {
28	                    for (const ability of rot.abilities) {
29	                        await WikiEnricher.downloadAsset(ability.name, iconDir);
30	                    }
31	                }
32	
33	                const data = {
34	                    boss,
35	                    lastUpdated: new Date().toISOString(),
36	                    bestiary,
37	                    rotations
38	                };
39	
40	                const filename = `${boss.replace(/[^a-z0-9]/gi, '_').toLowerCase()}.json`;
41	                writeFileSync(join(this.DATA_DIR, filename), JSON.stringify(data, null, 2));
42	                logger.info({ boss, rotations: rotations.length }, 'Saved PVME data');
43	            } catch (err) {
44	                logger.error({ boss, err }, 'Failed to ingest boss data');
45	            }
46	        }
47	    }
48	}
