1	import { WebSocketServer, WebSocket } from 'ws';
2	import { createServer } from 'http';
3	import { existsSync, mkdirSync, appendFileSync, readFileSync } from 'fs';
4	import { join, extname } from 'path';
5	import { createLogger } from './logger.js';
6	
7	const logger = createLogger('CombatHUDBridge');
8	
9	export interface HUDStateUpdate {
10	    type: 'STATE_UPDATE';
11	    adrenaline: number;
12	    activeArchetype: string;
13	    combatStyle?: string;
14	    activePhase?: string;
15	    targetName?: string;
16	    targetHp?: number;
17	    lastAction?: string;
18	    activeRotation?: string;
19	    nextAbility?: string;
20	    kernelPhase?: string;
21	    learningTrace?: any;
22	}
23	
24	export interface HUDLogUpdate {
25	    type: 'LOG_UPDATE';
26	    message: string;
27	    level: 'info' | 'action';
28	}
29	
30	export interface HitsplatUpdate {
31	    type: 'HITSPLAT';
32	    value: number;
33	    kind: 'DAMAGE' | 'CRIT' | 'HEAL' | 'BLOCK' | 'POISON' | 'XP';
34	    entityId: string;
35	}
36	
37	export class CombatHUDBridge {
38	    private static instance: CombatHUDBridge;
39	    private wss: WebSocketServer | null = null;
40	    private clients: Set<WebSocket> = new Set();
41	    private startTime: number = Date.now();
42	    private lastTickReceived: number = 0;
43	    private traceBuffer: any[] = []; // Simple buffer for the dashboard to pull from
44	
45	    private constructor() {
46	        this.initServer();
47	    }
48	
49	    public static getInstance(): CombatHUDBridge {
50	        if (!CombatHUDBridge.instance) {
51	            CombatHUDBridge.instance = new CombatHUDBridge();
52	        }
53	        return CombatHUDBridge.instance;
54	    }
55	
56	    private initServer() {
57	        try {
58	            const server = createServer((req, res) => {
59	                if (req.url === '/health') {
60	                    res.writeHead(200, { 'Content-Type': 'application/json' });
61	                    res.end(JSON.stringify({ 
62	                        status: 'alive', 
63	                        port: 8080, 
64	                        uptimeMs: Date.now() - this.startTime,
65	                        clientsConnected: this.clients.size,
66	                        lastTickReceived: this.lastTickReceived,
67	                        causalTracesBuffered: this.traceBuffer.length
68	                    }));
69	                    return;
70	                }
71	
72	                // MIME types for static serving
73	                const MIME_TYPES: Record<string, string> = {
74	                    '.html': 'text/html',
75	                    '.js': 'application/javascript',
76	                    '.css': 'text/css',
77	                    '.json': 'application/json',
78	                    '.png': 'image/png',
79	                    '.jpg': 'image/jpeg',
80	                    '.gif': 'image/gif',
81	                    '.svg': 'image/svg+xml',
82	                    '.ico': 'image/x-icon',
83	                };
84	
85	                const url = new URL(req.url || '/', `http://localhost`);
86	                const pathname = url.pathname;
87	
88	                // ─── API: /api/enrich ───
89	                if (pathname === '/api/enrich') {
90	                    res.writeHead(200, { 'Content-Type': 'application/json', 'Access-Control-Allow-Origin': '*' });
91	                    try {
92	                        const type = url.searchParams.get('type') || 'npc';
93	                        const nameQuery = url.searchParams.get('name') || '';
94	                        const idQuery = url.searchParams.get('id') || '';
95	
96	                        const dumpDir = 'D:\\sovereign\\cache_pedagogy\\json_dumps';
97	                        const fileMap: Record<string, string> = { npc: 'npcs.json', item: 'items.json', object: 'objects.json' };
98	                        const fileName = fileMap[type] || 'npcs.json';
99	                        const dataPath = join(dumpDir, fileName);
100	
101	                        if (!existsSync(dataPath)) {
102	                            res.end(JSON.stringify({ error: `Data file not found: ${fileName}` }));
103	                            return;
104	                        }
105	
106	                        const entries: any[] = JSON.parse(readFileSync(dataPath, 'utf8'));
107	                        let match: any = null;
108	
109	                        if (idQuery) {
110	                            match = entries.find((e: any) => e.id === parseInt(idQuery));
111	                        } else if (nameQuery) {
112	                            const q = nameQuery.toLowerCase();
113	                            match = entries.find((e: any) => e.name && e.name.toLowerCase() === q)
114	                                 || entries.find((e: any) => e.name && e.name.toLowerCase().includes(q));
115	                        }
116	
117	                        if (match) {
118	                            res.end(JSON.stringify({
119	                                name: match.name,
120	                                role: type.toUpperCase(),
121	                                cacheData: { id: match.id, hp: match.hp || match.hitpoints || 0, ...match },
122	                                location: match.location || 'Cache Substrate',
123	                                url: `https://runescape.wiki/w/${encodeURIComponent(match.name.replace(/ /g, '_'))}`
124	                            }));
125	                        } else {
126	                            res.end(JSON.stringify({ name: nameQuery || `ID ${idQuery}`, role: type.toUpperCase(), error: 'Not found in cache dump' }));
127	                        }
128	                    } catch (e) {
129	                        res.end(JSON.stringify({ error: 'Enrich API error' }));
130	                    }
131	                    return;
132	                }
133	
134	                // ─── API: /api/actionbar ───
135	                if (pathname === '/api/actionbar') {
136	                    res.writeHead(200, { 'Content-Type': 'application/json', 'Access-Control-Allow-Origin': '*' });
137	                    try {
138	                        const regPath = 'D:\\sovereign\\memory\\pedagogy\\sovereign_ability_registry.json';
139	                        if (existsSync(regPath)) {
140	                            const reg = JSON.parse(readFileSync(regPath, 'utf8'));
141	                            const style = (url.searchParams.get('style') || 'ranged').toLowerCase();
142	                            const styleAbilities = reg.styles?.[style] || [];
143	                            const slots = styleAbilities.slice(0, 14).map((name: string, i: number) => ({
144	                                slotIndex: i,
145	                                abilityId: name.toLowerCase().replace(/[\s()]/g, '_'),
146	                                abilityName: name,
147	                                style,
148	                                tier: 'basic',
149	                                cooldownTotal: 5,
150	                                adrenalineCost: 0,
151	                                adrenalineThreshold: 0
152	                            }));
153	                            res.end(JSON.stringify({ style, slots }));
154	                        } else {
155	                            res.end(JSON.stringify({ style: 'ranged', slots: [] }));
156	                        }
157	                    } catch (e) {
158	                        res.end(JSON.stringify({ style: 'ranged', slots: [] }));
159	                    }
160	                    return;
161	                }
162	
163	                // ─── Mounted Sovereign Data Directories ───
164	                const mountedPaths: Record<string, string> = {
165	                    '/interfaces/': 'D:\\sovereign\\cache_pedagogy\\atlas\\interfaces',
166	                    '/dumps/': 'D:\\sovereign\\cache_pedagogy\\json_dumps',
167	                    '/pedagogy/': 'D:\\sovereign\\memory\\pedagogy',
168	                    '/scratch/': join(process.cwd(), 'scratch'),
169	                    '/pvme/': join(process.cwd(), 'data', 'pvme'),
170	                    '/atlas/': join(process.cwd(), 'atlas'),
171	                };
172	
173	                for (const [prefix, root] of Object.entries(mountedPaths)) {
174	                    if (pathname.startsWith(prefix)) {
175	                        const relativePath = pathname.slice(prefix.length);
176	                        const resolved = join(root, relativePath);
177	                        try {
178	                            if (existsSync(resolved)) {
179	                                const ext = extname(resolved);
180	                                const mime = MIME_TYPES[ext] || 'application/octet-stream';
181	                                const data = readFileSync(resolved);
182	                                res.writeHead(200, { 'Content-Type': mime, 'Access-Control-Allow-Origin': '*' });
183	                                res.end(data);
184	                            } else {
185	                                res.writeHead(404, { 'Content-Type': 'text/plain' });
186	                                res.end(`Not found: ${req.url}`);
187	                            }
188	                        } catch (e) {
189	                            res.writeHead(500);
190	                            res.end('Internal server error');
191	                        }
192	                        return;
193	                    }
194	                }
195	
196	                // ─── Static Files from public/ ───
197	                const publicDir = join(process.cwd(), 'public');
198	                let filePath = pathname === '/' ? '/unified_diagnostic.html' : pathname;
199	                filePath = join(publicDir, filePath);
200	
201	                try {
202	                    if (existsSync(filePath)) {
203	                        const ext = extname(filePath);
204	                        const mime = MIME_TYPES[ext] || 'application/octet-stream';
205	                        const data = readFileSync(filePath);
206	                        res.writeHead(200, { 'Content-Type': mime });
207	                        res.end(data);
208	                    } else {
209	                        res.writeHead(404, { 'Content-Type': 'text/plain' });
210	                        res.end(`Not found: ${req.url}`);
211	                    }
212	                } catch (e) {
213	                    res.writeHead(500);
214	                    res.end('Internal server error');
215	                }
216	            });
217	
218	            this.wss = new WebSocketServer({ server });
219	            this.wss.on('connection', (ws) => {
220	                this.clients.add(ws);
221	                logger.info('HUD client connected');
222	                
223	                ws.on('close', () => {
224	                    this.clients.delete(ws);
225	                    logger.info('HUD client disconnected');
226	                });
227	            });
228	
229	            server.listen(8080, () => {
230	                logger.info('Combat HUD Bridge active on ws://localhost:8080 (Health: http://localhost:8080/health)');
231	            });
232	
233	            server.on('error', (e: any) => {
234	                if (e.code === 'EADDRINUSE') {
235	                    logger.error('Port 8080 already in use. HUD Bridge failed to bind.');
236	                } else {
237	                    logger.error({ err: e }, 'HUD Bridge server error');
238	                }
239	            });
240	        } catch (e) {
241	            logger.error({ err: e }, 'Failed to start HUD Bridge');
242	        }
243	    }
244	
245	    public broadcast(payload: HUDStateUpdate | HUDLogUpdate | HitsplatUpdate) {
246	        const message = JSON.stringify(payload);
247	        this.clients.forEach((client) => {
248	            if (client.readyState === WebSocket.OPEN) {
249	                client.send(message);
250	            }
251	        });
252	    }
253	
254	    public log(message: string, level: 'info' | 'action' = 'info') {
255	        this.broadcast({ type: 'LOG_UPDATE', message, level });
256	    }
257	
258	    public updateState(adrenaline: number, archetype: string, lastAction?: string, activeRotation?: string, nextAbility?: string, combatStyle?: string, activePhase?: string, targetHp?: number, kernelPhase?: string, learningTrace?: any) {
259	        this.lastTickReceived = Date.now();
260	        const payload: HUDStateUpdate = {
261	            type: 'STATE_UPDATE',
262	            adrenaline,
263	            activeArchetype: archetype,
264	            combatStyle,
265	            activePhase,
266	            targetHp,
267	            lastAction,
268	            activeRotation,
269	            nextAbility,
270	            kernelPhase,
271	            learningTrace
272	        };
273	        this.broadcast(payload);
274	        
275	        // Simple ring buffer for causal traces (learningTrace)
276	        if (learningTrace) {
277	            this.traceBuffer.push(learningTrace);
278	            if (this.traceBuffer.length > 50) {
279	                const oldest = this.traceBuffer.shift();
280	                this.serializeTrace(oldest);
281	            }
282	        }
283	    }
284	
285	    private serializeTrace(trace: any) {
286	        try {
287	            const logDir = 'logs';
288	            if (!existsSync(logDir)) mkdirSync(logDir);
289	            const date = new Date().toISOString().split('T')[0];
290	            const logFile = join(logDir, `causal_traces_${date}.jsonl`);
291	            appendFileSync(logFile, JSON.stringify(trace) + '\n');
292	        } catch (e) {
293	            // Silently fail if log cannot be written to avoid interfering with bridge
294	        }
295	    }
296	
297	    public hitsplat(value: number, kind: HitsplatUpdate['kind'] = 'DAMAGE', entityId: string = 'target') {
298	        this.broadcast({ type: 'HITSPLAT', value, kind, entityId });
299	    }
300	}
